"""ParkFlow-specific composition layer; retains the sourced analytical deck."""
from html import escape


def wordmark():
    return '<span class="wordmark" aria-label="ParkFlow">park<span>flow</span><svg viewBox="0 0 36 24" aria-hidden="true"><path d="M2 8h26l-5-5M8 17h26l-5 5" fill="none" stroke="currentColor" stroke-width="2.8"/></svg></span>'


def detail_list(items):
    return '<dl class="detail-list">'+''.join(f'<div><dt>{a}</dt><dd>{b}</dd></div>' for a,b in items)+'</dl>'


def apply_direction(slides, api):
    by_id={s['id']:s for s in slides}
    for s in slides:
        s['title']=s['title'].replace('APPENDIX | ','Appendix / ').capitalize()
        for token in ['KL East','SDP','LPR','AI','API','SOP']:
            s['title']=s['title'].replace(token.lower(),token)
    def change(id,body,title=None,takeaway=None,cls=None):
        s=by_id[id];s['body']=body
        if title is not None:s['title']=title
        if takeaway is not None:s['takeaway']=takeaway
        if cls is not None:s['cls']=cls
    module,cols,chart,strip=api['module'],api['cols'],api['chart'],api['strip']
    logo=wordmark()

    change('cover',f'''<div class="cover-photo"><img src="assets/kl-east-exterior.jpg" alt="KL East Mall exterior, official property photograph"></div><div class="cover-copy">{logo}<p class="cover-context">A member service for KL East Mall</p><h1>A better arrival.<br>A reason to return.</h1><p class="cover-deck">Priority parking, verified at the gate.<br>A measured operating and investment case.</p><div class="cover-credit"><b>Team Hexa</b><span>Universiti Malaya · Hackathon 2026</span></div></div><div class="recipient"><span>Proposal for</span><img src="assets/sdp-logo.png" alt="Sime Darby Property official logo"></div>''',cls='cover premium-cover')
    by_id['cover']['sources']=['S1'];by_id['cover']['note']='Property image: official KL East Mall website. Independent Team Hexa proposal.'

    people=[('Leow Shen En','Product &amp; experience','Team lead · Data Science'),('Pohyi Chong','Forecasting &amp; models','Data Science'),('Isaac Teo','Analysis &amp; simulation','Data Science'),('Lee Jia Shern','Business case &amp; finance','Actuarial Science'),('Choong Zhuo Lin','AI engineering &amp; prototype','Artificial Intelligence')]
    change('team','<div class="team-composition"><div class="team-story"><h3>Team Hexa</h3><p>Universiti Malaya</p><div class="team-mission">Product, models,<br>operations and finance.<br><strong>One pilot decision.</strong></div><p class="note">Five students building a member parking proposition that can be tested in a real mall.</p></div><div class="team-roster">'+''.join(f'<article><h3>{name}</h3><div><b>{role}</b><p>{study}</p></div></article>' for name,role,study in people)+'</div></div>',title='The team behind ParkFlow',takeaway='A working prototype and a transparent investment case, built across five complementary roles.',cls='opening')

    change('executive','<div class="executive-composition"><div class="recommendation"><span class="label">Recommendation</span><h3>Prove one zone.<br>Then decide to scale.</h3><p>Approve site discovery and a measured KL East pilot, with deployment funding released against a confirmed scope.</p><div class="budget-reference"><b>RM92k</b><span>Initial scope subtotal<br>Final installed cost to be confirmed</span></div></div><div class="recommendation-logic">'+''.join(f'<article><span>{label}</span><h3>{title}</h3><p>{copy}</p></article>' for label,title,copy in [('The opportunity','Make arrival part of the member benefit.','KL East has existing LPR. ParkFlow adds a proposed booking and zone-capacity service above the current payment journey.'),('The operating test','Protect the promise without wasting space.','Validate the deployed admission rule, real member uptake, local camera performance and the exception-handling SOP.'),('The investment test','Measure complete cost and incremental value.','Reconcile installed scope, central support and landlord capture before applying SDP’s agreed return hurdle.')])+'</div></div>',title='A bounded pilot, with a clear investment gate',takeaway='The decision is whether to validate the service at KL East before committing to a wider rollout.')

    change('context','<div class="site-composition"><figure class="property-photo"><img src="assets/kl-east-exterior.jpg" alt="Official exterior photograph of KL East Mall"><figcaption>KL East Mall · proposed lighthouse site</figcaption></figure><aside class="site-brief"><h3>Build on what<br>already exists.</h3>'+detail_list([('Published today','Cashless parking, LPR and online payment.'),('Proposed addition','Bookable member-zone access near the lifts.'),('First investigation','Verify vendor interfaces, physical boundary and zone-level counts.')])+'<p class="note">Local search time, peak demand and willingness to pay require a baseline. Broad urban surveys are not a KL East demand estimate.</p></aside></div>',title='Start with the property, not a generic parking problem',takeaway='Existing LPR makes integration and reuse the first design decision.',cls='opening')

    change('alternatives','<div class="brand-comparisons"><article><div class="comparison-brand"><img src="assets/1utama.png" alt="1 Utama official logo"><img src="assets/onecard.png" alt="ONECARD official logo"></div><div><h3>Member access is established</h3><p>ONECARD publishes member preferred parking and LPR-linked access/payment.</p></div><aside>Compare the fulfilment promise,<br>not membership alone.</aside></article><article><div class="comparison-brand"><img class="wide-logo" src="assets/sunway-pyramid.png" alt="Sunway Pyramid official logo"></div><div><h3>Premium areas and reservations exist</h3><p>Sunway’s FAQ covers preferred parking and EV bay reservation via ParkEasy.</p></div><aside>Reservation is a capability<br>to evaluate, not a uniqueness claim.</aside></article><article class="proposition-row"><div>'+logo+'</div><div><h3>A pooled, auditable member service</h3><p>Verified admissions, advisory forecasts and a shared record of commitments and exceptions.</p></div><aside>Prove reliability, capacity efficiency<br>and incremental member value.</aside></article></div>',title='Differentiate on the operating promise',takeaway='Published parking programmes establish the category; the pilot must establish ParkFlow’s added value.')

    change('service','<div class="service-spatial"><figure><img src="assets/priority-zone-pilot-concept.png" alt="Illustrative proposed Priority Zone with entry gate, pooled bays and nearby lifts"><figcaption>Illustrative concept only. Not a surveyed or approved KL East floor plan.</figcaption></figure><div class="service-rule"><h3>One shared zone.<br>Any free bay.</h3><p>Members reserve access to pooled capacity. The system does not assign an individual parking bay.</p><p class="note">Boundary, arrival window, cancellation terms and assistance require operator approval.</p></div></div><div class="journey-ribbon">'+''.join(f'<div><b>{a}</b><span>{b}</span></div>' for a,b in [('Reserve','Eligible member + plate'),('Verify','Entitlement + capacity'),('Park','Any available zone bay'),('Release','Exit closes the record')])+'</div>',title='Make the service tangible',takeaway='A dedicated zone by the lifts, with controlled entry and reconciled exit.',cls='opening')

    change('member','<div class="member-composition"><div class="member-story"><h3>Before the journey,<br>remove the uncertainty.</h3>'+detail_list([('Choose','See eligibility, the extra booking fee and an arrival window.'),('Arrive','Use the registered plate and directions to the correct zone.'),('Resolve','Reach support for late arrival, a plate mismatch or a refund.')])+'<p class="note">RM4 weekday / RM5 peak is a proposed pricing test, additional to normal parking charges.</p></div><div class="member-screens"><figure><img src="assets/app-home.webp" alt="ParkFlow member app booking prototype"><figcaption>Find and reserve</figcaption></figure><figure><img src="assets/app-guidance.webp" alt="ParkFlow member app arrival guidance prototype"><figcaption>Navigate and arrive</figcaption></figure></div></div>',title='A member journey that stays in one place',takeaway='Booking, guidance and help should feel like a single service.',cls='opening')

    change('operator','<div class="operator-composition"><figure><img src="assets/op-overview.webp" alt="ParkFlow operator dashboard prototype showing capacity and parking operations"><figcaption>Working interface prototype · simulated data</figcaption></figure><aside><h3>A record the<br>operator can explain.</h3>'+detail_list([('Before entry','Check promises and reconciled capacity.'),('During service','Monitor stale data, no-shows and exceptions.'),('At review','Trace every override to its reason, user and timestamp.')])+'<p class="note">Assistance and emergency egress remain available during faults.</p></aside></div>',title='Give the operator one coherent view',takeaway='The operational record connects entry, occupancy, commitments and exceptions.',cls='opening')

    bays=''.join(f'<div class="account-bay {"held" if i<5 else "buffer" if i==5 else "offer"}"><span>{"Promise" if i<5 else "Buffer" if i==5 else "Available"}</span></div>' for i in range(8))
    change('admission','<div class="capacity-composition"><div class="capacity-exhibit"><h3>Eight verified free bays, accounted for</h3><div class="account-bays">'+bays+'</div><p class="note">Accounting illustration. Individual physical bays are not assigned.</p><div class="capacity-math"><b>8 <small>verified free</small></b><span>−</span><b>5 <small>outstanding promises</small></b><span>−</span><b>1 <small>proposed buffer</small></b><span>=</span><b class="blue">2 <small>additional promises now</small></b></div></div><div class="control-distinction"><article><h3>Verified control protects access</h3><p>Commit only against a reconciled capacity guard. Freeze new promises when counts or connectivity become uncertain.</p></article><article><h3>Forecasts improve planning</h3><p>Advise arrival choices and operating modes. Predicted departures alone do not create bookable capacity.</p></article></div></div>',title='Protect the commitment at the gate',takeaway='Current verified capacity and forecast availability serve different purposes.')

    change('integration','<div class="architecture"><div class="architecture-inputs"><h3>Connect existing systems</h3><article><b>Member identity</b><span>Eligibility, plate and payment reference</span></article><article><b>Vehicle events</b><span>Entry / exit LPR and reconciled counts</span></article><article><b>Occupancy history</b><span>CCTV, local labels and timestamped use</span></article></div><div class="architecture-core"><div><span class="label">ParkFlow control layer</span><h3>Capacity guard<br>+ promise ledger</h3><p>Verified counts · entitlement<br>expiry · assisted exceptions</p></div><div class="forecast-lane"><b>Separate advisory layer</b><span>Forecasts, uncertainty and arrival guidance</span></div></div><div class="architecture-outputs"><h3>Return an auditable service</h3><article><b>Member</b><span>Booking, direction and assistance</span></article><article><b>Operator</b><span>Admission, override and reconciliation</span></article><article><b>SDP</b><span>Performance, cost and value review</span></article></div></div>'+strip('<strong>Integration gate:</strong> confirm API/SSO access, incumbent vendor rights, zone coverage and privacy roles before procurement.'),title='Integrate the service, reuse the infrastructure',takeaway='Buy additional hardware only where the existing site and interfaces cannot support the agreed scope.')

    # Composite capability exhibit: diagnostic links + real asset + reuse logic.
    requirements=[('Zone-specific counts','Can existing entry/exit events isolate the proposed boundary?','The capacity guard needs a reconciled zone count, not only a mall-wide payment event.'),('Member entitlements','Can eligibility, plate and booking expiry connect to the controller?','The operator needs one valid admission decision and a traceable exception path.'),('Local perception','Can existing CCTV resolve indoor glare, pillars and blind spots?','Buy cameras only after local coverage and false-free errors are tested.')]
    change('integration','<div class="capability-composite"><div class="capability-diagnosis"><h3>Capabilities to validate</h3><div class="capability-columns"><span>Site / integration question</span><span>Why it matters</span></div>'+''.join(f'<article><div><b>{name}</b><p>{question}</p></div><span class="diagnostic-arrow" aria-hidden="true">→</span><div><p>{impact}</p></div></article>' for name,question,impact in requirements)+'<div class="capability-conclusion"><strong>First action:</strong> a focused site and vendor audit, before expanding the hardware scope.</div></div><aside class="capability-assets"><figure><img src="assets/kl-east-exterior.jpg" alt="KL East Mall official property image"><figcaption>Existing property, potential reuse.</figcaption></figure><h3>Build on the installed foundation</h3>'+detail_list([('LPR','Published by KL East; confirm zone access and protocol.'),('CCTV','Survey coverage before pricing additional cameras.'),('Mall touchpoint','Confirm member identity, API rights and payment settlement.')])+'</aside></div>',title='Close capability gaps without duplicating the site',takeaway='The public record establishes LPR; the survey must establish the additional integration and control requirements.')

    # Three linked sanity checks, modeled after the supplied feasibility exhibit.
    def mini_bars(values,labels,unit):
        parts=[api['txt'](15,22,unit,16,'#53647a','start')]
        high=max(values)*1.2
        for j,(v,label) in enumerate(zip(values,labels)):
            x=70+j*160;h=v/high*135;y=175-h
            parts += [f'<rect x="{x}" y="{y}" width="80" height="{h}" fill="{"#8795a7" if j==0 else "#245bd8"}"/>',api['txt'](x+40,y-10,f'{v:,.0f}',20,weight=650)]
            for k,line in enumerate(label.split('|')):parts.append(api['txt'](x+40,200+k*20,line,15))
        return api['svg_wrap'](parts,245,'Comparison: '+', '.join(f'{label.replace("|"," ")} {v:,.0f}' for v,label in zip(values,labels))).replace('0 0 900 245','0 0 390 245')
    annual_bookings=104*30+261*7.5
    net_per_booking=api['R']['net']/annual_bookings
    import math
    break_even=math.ceil(10500/net_per_booking)
    checks=[('Is zone OPEX covered?',mini_bars([break_even,annual_bookings],['Operating|break-even','Base-case|bookings'],'Annual bookings, same fee mix'),'<b>Base case clears zone OPEX.</b> At the modeled fee mix, approximately 2,918 annual paid bookings cover RM10.5k. The base assumes 5,078.','Demand and payment costs still require validation.'),('Does booking repay capital?',mini_bars([api['R']['contribution'],16300],['Booking|contribution','5-year|requirement'],'Annual contribution (RM)'),'<b>A recovery gap remains.</b> RM7.8k booking contribution falls below the RM16.3k annual requirement for five-year simple recovery.','Additional net benefit required: RM8,524.60 a year.'),('Can visits close that gap?',mini_bars([api['GAP5'],13*52*260*.05],['Annual|recovery gap','13 extra|weekly visits'],'Annual net benefit (RM)'),'<b>Thirteen weekly visits illustrate the bridge.</b> At RM260 spend and 5% effective net capture, 13 additional visits a week yield RM8,788 a year.','Capture and genuinely incremental visits remain pilot questions.')]
    sanity_body='<div class="sanity-context"><b>One model across all three checks.</b><span>Fee mix → operating contribution → capital hurdle → incremental visit requirement.</span></div><div class="sanity-panels">'+''.join(f'<article><h3>{title}</h3><figure>{svg}</figure><p>{copy}</p><div class="sanity-verdict">{verdict}</div></article>' for title,svg,copy,verdict in checks)+'</div>'
    template=dict(by_id['booking-return']);template.update(id='sanity-checks',title='Three checks connect demand, cash and capital',takeaway='The operating case can be positive while the complete investment case still needs additional value.',body=sanity_body,sources=['M1','S4'],note='Illustrative inputs, not a forecast. Excludes central support, tax and extra capital. Five-year recovery is a comparison case; 5% capture and RM260 basket are scenarios.',cls='')
    slides.insert(next(i for i,s in enumerate(slides) if s['id']=='booking-return')+1,template)

    # A paired quantitative exhibit replaces the policy table without changing data.
    parts=[]
    T=api['txt']
    parts += [T(0,30,'Policy tested',21,anchor='start',weight=700),T(370,30,'Bookings honoured',21,anchor='start',weight=700),T(710,30,'Idle protected bay-hours*',21,anchor='start',weight=700)]
    for i,(label,rel,idle) in enumerate([('No priority control',85.5,0),('Fixed VIP section',99.9,19),('Fixed rule: 5 safety bays',100,23),('Forecast policy',100,5)]):
        y=92+i*90;c='#245bd8' if i==3 else '#8795a7'
        parts += [T(0,y+15,label,22,anchor='start',weight=700 if i==3 else 400),f'<line x1="370" y1="{y}" x2="625" y2="{y}" stroke="#e2e7ee" stroke-width="16"/>',f'<line x1="370" y1="{y}" x2="{370+(rel-80)/20*255}" y2="{y}" stroke="{c}" stroke-width="16"/>',T(641,y+7,f'{rel:.1f}%',21,anchor='start',weight=700),f'<rect x="770" y="{y-10}" width="{idle*8}" height="20" fill="{c}"/>',T(775+idle*8,y+7,str(idle),22,anchor='start',weight=700)]
    parts += [T(370,430,'Reliability axis starts at 80%',17,'#53647a','start'),T(770,430,'Lower is better',17,'#53647a','start')]
    sim=api['svg_wrap'](parts,465,'Recorded policy simulation: booking reliability and idle protected bay-hours by policy.').replace('0 0 900 465','0 0 1040 465')
    change('simulation',chart(sim,'1,000 simulated busy days · 100-bay zone · same synthetic demand.')+'<div class="evidence-boundary-row"><div><b>What the model shows</b><p>A trade-off between reliability and unused protected capacity under different policies.</p></div><div><b>What the pilot must test</b><p>The proposed current-capacity guard differs from the forecast policy. Its efficiency is not established by this comparison.</p></div></div>',title='Show the operating trade-off transparently',takeaway='The recorded forecast policy is efficient in simulation; the deployed admission rule still needs validation.')

    # Preserve the existing analytical charts; replace their generic right-hand lists.
    change('booking-return',cols(module('Annual booking-fee bridge',chart(api['waterfall']([api['R']['gross'],-api['R']['operator'],-api['R']['processing'],-10500,api['R']['contribution']],['Gross booking|fees','Operator|20% share','Processing|2% allowance','Zone running|allowance','Operating|contribution'],26000),'365-day illustration; 104 peak / 261 weekday days.')),module('Base planning inputs',detail_list([('Peak days','30 bookings / day × RM5'),('Weekdays','7.5 bookings / day × RM4'),('Allocations','20% operator + 2% processing'),('Zone running','RM10,500 per year')])+'<p class="note">Demand, shares and costs require validation. Booking fees sit above normal parking charges.</p>'),'wide-left'),title='Booking income contributes to the service',takeaway='The model leaves RM7.8k a year before central support, tax and capital recovery.')

    support='<div class="support-cases">'+''.join(f'<div><span>{cost} support / year</span><b>{value}</b></div>' for cost,value in [('RM0','RM7,775'),('RM12,000','−RM4,225'),('RM24,000','−RM16,225')])+'</div>'
    change('booking-sensitivity',cols(module('Annual contribution before central support',api['booking_sensitivity']()+'<p class="note">RM thousands; weekday / peak volumes are sensitivity inputs. Highlighted cell is the shared base case.</p>'),module('Support changes the outcome',support+'<p>Measure incidents, support minutes, refunds and actual payment fees before calling the service profitable.</p><p class="note">Support allocations are comparison cases, not staffing estimates.</p>'),'wide-left')+strip('<strong>Demand test:</strong> track paid conversion, eligible-member exposure and repeat usage alongside the operating metrics.'),title='Test volume and support cost together',takeaway='A positive zone contribution can disappear when central delivery effort is allocated.')

    change('commercial','<div class="ownership-map"><div class="ownership-sponsor"><span class="label">Accountable sponsor</span><h3>SDP mall management</h3><p>Owns the member proposition, pilot boundary and scale decision.</p><img src="assets/sdp-logo.png" alt="Sime Darby Property official organisation mark"></div><div class="ownership-workstreams">'+''.join(f'<article><h3>{role}</h3><p>{scope}</p><div><b>Decision evidence</b><span>{evidence}</span></div></article>' for role,scope,evidence in [('Parking operator','Admission, exceptions, staffing and ordinary parking settlement.','Operating agreement + signed SOP'),('Digital, IT & privacy','Interfaces, access, deployment and processing responsibilities.','API/SSO + data map + acceptance'),('Finance & procurement','Installed scope, support allocation, capture and return hurdle.','Comparable quotes + investment case')])+'</div></div>'+strip('<strong>Team and integrator:</strong> co-design, software delivery and approved site connection; suppliers confirm warranty and handover.'),title='Make ownership clear before deployment',takeaway='One sponsor connects the operating, technology and investment decisions.')

    stages=[('Before live','Baseline & readiness','Survey the zone, confirm vendor access, agree member terms, label local frames and sign the measurement plan.'),('Weeks 1–2','Supervised service','Observe booked arrivals, reconcile counts and test plate mismatch, stale data and support handling.'),('Weeks 3–6','Controlled comparison','Use matched peak windows or approved blocked/randomized policy days. Track fulfilment and idle capacity.'),('Weeks 7–8','Value & investment review','Reconcile paid demand, support effort and cohort value. Extend measurement if the evidence is insufficient.')]
    change('pilot-design','<div class="pilot-timeline">'+''.join(f'<article><span>{period}</span><h3>{title}</h3><p>{copy}</p></article>' for period,title,copy in stages)+'</div><div class="test-design"><div><h3>Operational comparison</h3><p>Served accepted arrivals, reconciled count drift, idle held bay-hours while demand is refused, and the cause of every failure.</p></div><div><h3>Commercial comparison</h3><p>Exposed eligible members, paid conversion, matched/control revisit outcomes and complete support-adjusted cost.</p></div></div>',title='An eight-week trial with a baseline before launch',takeaway='Separate service reliability from commercial uplift and define the comparison before the first paid booking.')

    change('risk','<div class="fault-flow"><div class="fault-origin"><h3>Can the operator trust the current state?</h3><p>Verified plate · current counts · live controller · valid entitlement</p></div><div class="fault-branches"><article class="healthy"><b>Yes</b><h3>Apply the capacity guard</h3><p>Admit eligible vehicles only when the agreed promise and buffer rules pass.</p><span>Owner: parking operator</span></article><article class="uncertain"><b>No / uncertain</b><h3>Pause new commitments</h3><p>Use assisted verification, preserve egress, log the incident and reconcile before restarting.</p><span>Owner: operator + IT / integrator</span></article></div></div><div class="exception-rail"><div><b>Member exceptions</b><span>Published grace, no-show, overstay and refund rules.</span></div><div><b>Data incident</b><span>Restricted access, evidence preservation and SDP privacy escalation.</span></div><div><b>Low paid demand</b><span>Review scope and price with finance before expansion.</span></div></div>',title='Design the exception path as carefully as entry',takeaway='The first response to uncertainty is a safe operating state and a traceable recovery process.')

    phases=[('0–6 months','Prove at KL East',['Survey + local baseline','Eight-week live trial','SOP + full-cost review'],'Value gate: service and economics'),('6–24 months','Build the SDP system',['Qualify Elmina + KLGCC','Shared interfaces + reporting','Repeatable support + onboarding'],'Repeatability gate: approved sites'),('24–60 months','Scale by contract',['External mall-group demand','Versioned APIs + SLA','Onboarding + support margin'],'Commercial gate: signed economics')]
    change('horizons','<div class="horizon-composition"><div class="horizon-axis"><span>Validated service</span><span>Repeatable operating system</span><span>Contracted platform</span></div><div class="horizon-stages">'+''.join(f'<article><p class="period">{p}</p><h3>{h}</h3><ul>'+''.join(f'<li>{x}</li>' for x in items)+f'</ul><div class="value-gate">{gate}</div></article>' for p,h,items,gate in phases)+'</div><div class="portfolio-line"><img src="assets/sdp-logo.png" alt="Sime Darby Property logo"><div><b>Three wholly owned malls</b><p>KL East, Elmina Lakeside and KLGCC. JV opportunities need separate rights, approvals and economics.</p></div></div></div>',title='Scale the operating system in three horizons',takeaway='The next horizon begins when evidence clears the gate, rather than when a date alone is reached.')

    change('decision','<div class="decision-composition"><div class="decision-ask"><span class="label">Requested now</span><h3>Authorize discovery.<br>Set the pilot up to decide.</h3><p>Nominate a KL East sponsor and operator counterpart. Enable the site survey, integration discussions and baseline measurement.</p><div class="decision-budget"><b>RM92k</b><span>Initial planning subtotal<br>Final installed scope pending</span></div></div><div class="decision-deliverables"><h3>Return with four decision inputs</h3>'+detail_list([('Feasible site','Zone boundary, incumbent interfaces and approved integration.'),('Complete cost','Installed quotes, support, tax and contingency.'),('Ready operator','Signed SOP, member terms and fault drills.'),('Credible value test','Baseline, cohort, measurement plan and go/adapt/stop criteria.')])+'</div></div>',title='Approve a bounded path to the pilot',takeaway='Release deployment funding once the scope and measurement plan are confirmed.')

    change('thanks',f'<div class="thank-composition"><div>{logo}<h2>Thank you.</h2><p>Team Hexa · Universiti Malaya</p><span>Questions &amp; discussion</span></div><figure><img src="assets/kl-east-exterior.jpg" alt="KL East Mall exterior"><figcaption>Supporting appendix follows.</figcaption></figure></div>',cls='thank premium-thank')

    # Deep detail remains available in the appendix; avoid red-as-brand remnants.
    for s in slides:
        s['body']=s['body'].replace('Pale red = more than 20 visits; blue-grey = 12 or fewer.','Darker cells = more than 20 visits; blue-grey = 12 or fewer.').replace('pale red','darker cells')
